 const largeAward=[10000,12000,8500][idx]||10000,standardAward=[5000,6000,4000][idx]||5000,incentive=[5000,4500,3500][idx]||5000;
 return {agreementType:advisor?'Advisor engagement':'Internal POC engagement',status:'Active',role:advisor?'Business Development Advisor':'Internal EXL POC',exlContact:'Jordan Lee · SOW owner',agreementDate:'2026-11-01',sowStart:'2026-11-01',sowEnd:'2027-04-30',extensionDeadline:'2027-04-26',commissionWindowEnd:'2027-10-29',location:'Remote (US); travel pre-approved',governingLaw:'New York, USA',paymentTerms:'NET 30 from invoice',hourlyRate,firstMonthCap:firstCap,monthlyCap,extraHours:'Prior written approval',travelExpenses:'Actuals, pre-approved, on monthly invoice',oneTimeIncentive:incentive,largeMsaThreshold:100,largeMsaCommission:largeAward,otherMsaCommission:standardAward,sowYearOnePercent:4.5,sowYearTwoPercent:2,hoursUsed,hoursCap:monthlyCap,deliverables:[{name:'Meeting preparation & planning',target:20,actual:9},{name:'Prospect meetings set up',target:10,actual:4},{name:'Workshops / speaking events',target:3,actual:1},{name:'New MSA or new cost-center win',target:1,actual:0}],compliance:[{name:'Confidentiality / NDA',status:'Complete',detail:'On file'},{name:'Insurance documentation',status:'Review needed',detail:'Documentation pending'},{name:'Security and privacy training',status:'Complete',detail:'Annual refresher'},{name:'Tax and payment setup',status:'In progress',detail:'Before first invoice'}],scope:advisor?'Support relationship development, prepare for club meetings, and coordinate discovery with internal specialists.':'Coordinate internal points of contact, meeting preparation, and follow-through for club conversations.',conditions:'Protect confidential information, get approval before sharing materials externally, and do not make commitments on behalf of EXL.',restrictions:'No authority to bind EXL or a club. Confidentiality survives the engagement. Any post-term commission eligibility is subject to the signed agreement and a sample six-month window.'}
