function contractFor(id){const person=db.users.find(u=>u.id===id),c={...sampleContract(person||user()),...(db.contracts?.[id]||{})};c.agreementType=String(c.agreementType||'').replace(/^Sample /,'');if(c.status==='Illustrative sample')c.status='Active';c.conditions=String(c.conditions||'').replace(/^Illustrative only:\s*/,'');return c}
