const dt=(offset=0)=>{const d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()+offset);return d.toISOString().slice(0,10)};
function freshDB(){
 const clubs=[];Object.entries(LEAGUES).forEach(([league,names])=>names.forEach((name,i)=>clubs.push({id:`${league}-${i+1}`,league,name})));
 const ids=Object.fromEntries(clubs.map(c=>[c.name,c.id]));
 const interactions=[
  {id:'i-1',clubId:ids['New York Yankees'],date:dt(-2),stakeholders:[{name:'Morgan Ellis',role:'VP, Partnerships'},{name:'Chris Patel',role:'Director, Marketing'}],participants:[{name:'Avery Morgan',role:'Advisor'},{name:'Taylor Brooks',role:'Internal POC'}],summary:'Discussed improving sponsor renewal workflows and how a more consistent sales motion could support the upcoming planning cycle. Team is interested in seeing examples from comparable clubs.',capabilities:['Marketing in a Box','Ticket Sales Accelerator'],other:'',owner:'u-avery',sample:true,followups:[{id:'f-1',description:'Share the sponsorship activation overview and two relevant case studies',owner:'u-avery',due:dt(2),status:'Open'},{id:'f-2',description:'Introduce the club team to the ticketing solutions lead',owner:'u-taylor',due:dt(-1),status:'Open'}]},
  {id:'i-2',clubId:ids['New York Yankees'],date:dt(-20),stakeholders:[{name:'Morgan Ellis',role:'VP, Partnerships'}],participants:[{name:'Avery Morgan',role:'Advisor'}],summary:'Initial conversation about commercial priorities, current partner servicing process, and areas where the club would welcome practical examples.',capabilities:['Finance in a Box'],other:'',owner:'u-avery',sample:true,followups:[{id:'f-3',description:'Send a short overview of finance capabilities',owner:'u-avery',due:dt(-15),status:'Done'}]},
  {id:'i-3',clubId:ids['Boston Celtics'],date:dt(-5),stakeholders:[{name:'Jordan Kim',role:'Chief Revenue Officer'}],participants:[{name:'Jamie Chen',role:'Advisor'}],summary:'Explored approaches to increase ticket sales conversion and improve coordination between marketing and sales teams before the next homestand.',capabilities:['Ticket Sales Accelerator','Other'],other:'Fan engagement journey mapping',owner:'u-jamie',sample:true,followups:[{id:'f-4',description:'Prepare a working session with ticket sales leadership',owner:'u-jamie',due:dt(4),status:'Open'}]},
  {id:'i-4',clubId:ids['Seattle Sounders FC'],date:dt(-11),stakeholders:[{name:'Alex Rivera',role:'VP, Business Operations'}],participants:[{name:'Taylor Brooks',role:'Internal POC'}],summary:'Reviewed collections process challenges and shared a high-level view of the collections accelerator. Club requested a next step focused on implementation considerations.',capabilities:['Collections Accelerator'],other:'',owner:'u-taylor',sample:true,followups:[{id:'f-5',description:'Send next step materials on collections process',owner:'u-taylor',due:dt(-3),status:'Open'}]},
  {id:'i-5',clubId:ids['Dallas Cowboys'],date:dt(-1),stakeholders:[{name:'Sam Carter',role:'SVP, Partnerships'}],participants:[{name:'Avery Morgan',role:'Advisor'},{name:'Jamie Chen',role:'Advisor'}],summary:'Followed up on earlier discussion and aligned on a discovery session with the partnership operations team. Club wants to understand what a first phase could look like.',capabilities:['Marketing in a Box','Finance in a Box'],other:'',owner:'u-avery',sample:true,followups:[{id:'f-6',description:'Coordinate discovery session with partnership operations',owner:'u-avery',due:dt(5),status:'Open'}]}
 ];
 interactions.forEach((i,n)=>{if(!i.nextStepType)i.nextStepType=NEXT_STEP_TYPES[n%NEXT_STEP_TYPES.length]});
 const meetings=[{id:'m-1',clubId:ids['New York Yankees'],date:dt(3),time:'10:00',interactionId:'i-1',participants:['Morgan Ellis','Avery Morgan'],agenda:'Review activation examples and agree on next steps',owner:'u-avery',status:'Planned'},{id:'m-2',clubId:ids['Boston Celtics'],date:dt(6),time:'13:30',interactionId:'i-3',participants:['Jordan Kim','Jamie Chen'],agenda:'Ticket sales working session',owner:'u-jamie',status:'Planned'},{id:'m-3',clubId:ids['Seattle Sounders FC'],date:dt(10),time:'15:00',interactionId:'i-4',participants:['Alex Rivera','Taylor Brooks'],agenda:'Collections accelerator next step',owner:'u-taylor',status:'Planned'}];
 return {users:SEED_USERS,clubs,interactions,meetings,contracts:{},activeUser:'u-admin',seeded:true};
}
const STORE='clubhouse_v1';let db;try{db=JSON.parse(localStorage.getItem(STORE))||freshDB()}catch(e){db=freshDB()};
function ensureCowboysSamples(owner){
 const club=db.clubs.find(c=>c.name==='Dallas Cowboys');if(!club)return false;
 db.interactions ||= [];db.meetings ||= [];let changed=false;
 const interactions=[
  {id:'sample-cowboys-interaction-2',clubId:club.id,date:dt(-8),stakeholders:[{name:'Sam Carter',role:'SVP, Partnerships'}],participants:[{name:'Avery Morgan',role:'Advisor'}],exlPoc:'Avery Morgan',clubPoc:'Sam Carter',clubPocDesignation:'SVP, Partnerships',summary:'Reviewed the club’s partnership priorities and discussed examples of sponsor servicing workflows. The team asked for a short overview to share internally.',capabilities:['Marketing in a Box'],other:'',nextStepType:'Materials to be shared',owner,sample:true,followups:[{id:'sample-cowboys-followup-2',description:'Share sponsor servicing overview with the partnerships team',owner,due:dt(2),status:'Open'}]},
  {id:'sample-cowboys-interaction-3',clubId:club.id,date:dt(-18),stakeholders:[{name:'Sam Carter',role:'SVP, Partnerships'},{name:'Dana Brooks',role:'Director, Partner Services'}],participants:[{name:'Avery Morgan',role:'Advisor'},{name:'Jamie Chen',role:'Advisor'}],exlPoc:'Avery Morgan',clubPoc:'Sam Carter',clubPocDesignation:'SVP, Partnerships',summary:'Introductory conversation about the Cowboys’ commercial operations, current priorities, and where EXL could share relevant experience.',capabilities:[],other:'',nextStepType:'Awaiting their response',owner,sample:true,followups:[]}
 ];
 interactions.forEach(item=>{if(!db.interactions.some(i=>i.id===item.id)){db.interactions.push(item);changed=true}});
 const meetings=[
  {id:'sample-cowboys-meeting-1',clubId:club.id,date:dt(4),time:'14:00',interactionId:'sample-cowboys-interaction-2',meetingType:'Discovery meeting',exlPoc:'Avery Morgan',clubPoc:'Sam Carter',clubPocDesignation:'SVP, Partnerships',participants:['Avery Morgan','Sam Carter'],agenda:'Review partnership operations priorities and agree on a discovery session.',owner,status:'Planned',sample:true},
  {id:'sample-cowboys-meeting-2',clubId:club.id,date:dt(11),time:'10:30',interactionId:'sample-cowboys-interaction-3',meetingType:'Working session',exlPoc:'Avery Morgan',clubPoc:'Dana Brooks',clubPocDesignation:'Director, Partner Services',participants:['Avery Morgan','Dana Brooks'],agenda:'Walk through sponsor servicing examples and discuss potential next steps.',owner,status:'Planned',sample:true}
 ];
 meetings.forEach(item=>{if(!db.meetings.some(m=>m.id===item.id)){db.meetings.push(item);changed=true}});
 const demoTimes={'m-1':'10:00','m-2':'13:30','m-3':'15:00','sample-cowboys-meeting-1':'14:00','sample-cowboys-meeting-2':'10:30'},demoLinks={'m-1':'i-1','m-2':'i-3','m-3':'i-4','sample-cowboys-meeting-1':'sample-cowboys-interaction-2','sample-cowboys-meeting-2':'sample-cowboys-interaction-3'};db.meetings.forEach(m=>{if(demoTimes[m.id]&&!m.time){m.time=demoTimes[m.id];changed=true}if(demoLinks[m.id]&&!m.interactionId){m.interactionId=demoLinks[m.id];changed=true}});
 return changed;
}
function save(){localStorage.setItem(STORE,JSON.stringify(db));fetch('/api/state',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({state:db})}).then(async r=>{if(!r.ok){const e=await r.json();toast(e.error||'Could not save to the local server')}}).catch(()=>{})}const user=()=>db.users.find(u=>u.id===db.activeUser)||db.users[0];const isAdmin=()=>user().role==='Admin';const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let page='home',selectedClub=null,clubTab='history',toastTimer,editingMeeting=null,editingInteraction=null,meetingToComplete=null,activeDigestItems=[],selectedContractUser='u-avery',editContractsMode=false,followupRange='open',calendarMonth=new Date(new Date().getFullYear(),new Date().getMonth(),1),selectedCalendarDate=dt();
const clubBy=id=>db.clubs.find(c=>c.id===id);const who=id=>db.users.find(u=>u.id===id)?.name||'Unassigned';
function exlPoc(i){if(i.exlPoc)return i.exlPoc;const p=(i.participants||[]).find(x=>(x.role||'').toLowerCase().includes('poc'))||(i.participants||[])[0];return p?.name||who(i.owner)}
function clubPoc(i){return i.clubPoc||(i.stakeholders||[])[0]?.name||'Not recorded'}
function clubPocDesignation(i){return i.clubPocDesignation||(i.stakeholders||[])[0]?.role||'Designation not recorded'}
function contactMeta(i){return 'EXL POC: '+esc(exlPoc(i))+' · Club/client POC: '+esc(clubPoc(i))+' — '+esc(clubPocDesignation(i))}
function nextStepPill(i){const tag=i.nextStepType||'Yet to be decided';const n=Math.max(0,NEXT_STEP_TYPES.indexOf(tag));return '<span class="next-step-tag next-tag-'+n+'">'+esc(tag)+'</span>'}
const initials=n=>n.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase();const visibleClubs=()=>db.clubs;const canSeeClub=id=>!!clubBy(id);const visibleInteractions=()=>db.interactions;const visibleMeetings=()=>db.meetings.filter(m=>m.status==='Planned');const allFollowups=()=>visibleInteractions().flatMap(i=>i.followups.map(f=>({...f,interaction:i,club:clubBy(i.clubId)}))).filter(f=>isAdmin()||f.owner===user().id||f.interaction.owner===user().id);
function fmt(d,opts={month:'short',day:'numeric',year:'numeric'}){if(!d)return '—';return new Date(`${d}T12:00:00`).toLocaleDateString('en-US',opts)}function relative(d){const delta=Math.round((new Date(d+'T12:00:00')-new Date(dt()+'T12:00:00'))/86400000);return delta<0?`${Math.abs(delta)}d overdue`:delta===0?'Due today':delta===1?'Due tomorrow':`Due in ${delta}d`}
function toast(msg){const el=document.createElement('div');el.className='toast';el.textContent=msg;document.body.append(el);setTimeout(()=>el.remove(),2800)}
function icon(name){return ({home:'◫',clubs:'▦',log:'＋',followups:'✓',digest:'◷',admin:'⚙'})[name]||'•'}
function app(){const u=user();document.getElementById('app').innerHTML=`<div class="app-shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">C</div><div><div class="brand-name">clubhouse</div><div class="brand-sub">Relationship activity</div></div></div><div class="nav-label">Workspace</div><nav class="nav">${[['home','Overview'],['clubs','Club directory'],...(isAdmin()?[]:[['log','Log interaction']]),['followups',isAdmin()?'Next steps summary':'My next steps'],...(isAdmin()?[]:[['contracts','My contract terms']])].map(([id,label])=>`<button class="${(page===id||(id==='home'&&page==='digest'))?'active':''}" data-page="${id}"><span class="nav-icon">${icon(id)}</span><span>${label}</span></button>`).join('')}${isAdmin()?`<div class="nav-divider"></div><div class="nav-label">Administration</div><button class="${page==='admin'?'active':''}" data-page="admin"><span class="nav-icon">${icon('admin')}</span><span>Workspace users</span></button><button class="${page==='contracts'?'active':''}" data-page="contracts"><span class="nav-icon">▤</span><span>Advisor contracts</span></button>`:''}</nav><div class="sidebar-bottom"><div class="demo-badge"><b>Demo workspace</b>Sample activity is labeled. Changes save to this workspace.</div><div class="profile"><div class="avatar">${initials(u.name)}</div><div><div class="profile-name">${esc(u.name)}</div><div class="profile-role">${esc(u.title)}</div></div><button class="signout" id="signout">Sign out</button></div></div></aside><main class="main"><header class="topbar"><div class="crumb">Relationship activity <span style="color:#bbc5bd"> / </span> ${pageLabel()}</div><div class="top-right"><span class="today">${new Date().toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric'})}</span><div class="user-small"><div class="avatar">${initials(u.name)}</div>${esc(u.name)}</div></div></header><div class="content" id="view"></div></main></div>`;renderPage();bindShell()}
function pageLabel(){return ({home:'Overview',clubs:'Club directory',log:'Log interaction',followups:isAdmin()?'Next steps summary':'My next steps',contracts:isAdmin()?'Advisor contracts':'My contract terms',digest:'Overview',admin:'Workspace users',club:'Club detail'})[page]||'Overview'}
function bindShell(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page==='digest'?'home':b.dataset.page;selectedClub=null;app()});$('#signout').onclick=async()=>{await fetch('/api/logout',{method:'POST'});loginPage();}}
function head(kicker,title,desc,action=''){return `<div class="page-head"><div><div class="greeting">${kicker}</div><h1 class="page-title">${title}</h1><p class="page-desc">${desc}</p></div>${action?`<div class="head-actions">${action}</div>`:''}</div>`}
function stat(label,note,value,ico){return `<div class="stat-card"><div class="stat-top"><div class="stat-label">${label}</div><div class="stat-icon">${ico}</div></div><div class="stat-num">${value}</div><div class="stat-note">${note}</div></div>`}
function clubShort(c){return c?.name||'Unknown club'}function leagueTag(l){return `<span class="pill blue">${l}</span>`}function capsTags(a,other){return (a||[]).map(c=>`<span class="pill ${c==='Other'?'orange':'green'}">${esc(c==='Other'&&other?`Other · ${other}`:c)}</span>`).join('')}
function renderPage(){const v=$('#view');if(page==='home')v.innerHTML=homePage();else if(page==='clubs')v.innerHTML=clubsPage();else if(page==='club')v.innerHTML=clubPage();else if(page==='log')v.innerHTML=isAdmin()?`${head('ADMIN VIEW','Interaction entry is for regular users','The Admin account reviews and manages activity. Sign in as an advisor or EXL POC to log a conversation.')}`:interactionForm();else if(page==='followups')v.innerHTML=followupsPage();else if(page==='digest')v.innerHTML=digestPage();else if(page==='admin')v.innerHTML=adminPage();else if(page==='contracts')v.innerHTML=contractPage();bindPage()}
function homePage(){return digestPage()}
function activityRow(i){const c=clubBy(i.clubId);return '<div class="activity-row"><div class="league-mark">'+(c?.league||'—')+'</div><div><div class="activity-club">'+esc(clubShort(c))+' '+(i.sample?'<span class="pill">Sample</span>':'')+'</div><div class="activity-meta">'+fmt(i.date)+' · '+contactMeta(i)+'</div><div class="activity-summary">'+esc(i.summary)+'</div><div class="cap-list">'+capsTags(i.capabilities,i.other)+'</div></div><button class="action-link" data-open-club="'+i.clubId+'">History →</button></div>'}
function meetingCard(m){const c=clubBy(m.clubId);const d=new Date(m.date+'T12:00:00');return `<div class="meeting-item"><div class="date-box"><span class="month">${d.toLocaleDateString('en-US',{month:'short'})}</span><span class="day">${d.getDate()}</span></div><div><div class="meeting-name">${esc(clubShort(c))} <span class="pill blue">${esc(m.meetingType||'Meeting')}</span>${m.sample?'<span class="pill sample-pill">Sample</span>':''}</div><div class="meeting-info">${esc(m.agenda||'Meeting planned')} · ${esc(m.exlPoc||m.participants?.join(', ')||who(m.owner))}${m.clubPoc?' · Club/client POC: '+esc(m.clubPoc)+(m.clubPocDesignation?' — '+esc(m.clubPocDesignation):''):''}</div></div></div>`}
function taskCard(f){return `<div class="task-item"><span class="task-dot ${f.due<dt()?'overdue':''}"></span><div style="min-width:0"><div class="task-name">${esc(f.description)}</div><div class="task-info">${esc(clubShort(f.club))} · ${relative(f.due)} · ${esc(who(f.owner))}</div></div></div>`}
function clubsPage(){const clubs=visibleClubs();return `${head('CLUB DIRECTORY','Know every relationship','Find a club to review history, upcoming meetings, and follow-through.',isAdmin()?'':'<button class="btn primary" data-page="log">＋ &nbsp; Log interaction</button>')}<div class="card"><div class="card-head"><div><div class="card-title">Professional sports clubs</div><div class="card-sub">${clubs.length} clubs across all five leagues</div></div><div class="filters"><input class="input search" id="club-search" placeholder="Search clubs…"><select class="select" id="league-filter"><option value="all">All leagues</option>${Object.keys(LEAGUES).map(l=>`<option>${l}</option>`).join('')}</select></div></div><div class="club-list" id="club-results">${clubCards(clubs)}</div></div>`}
function clubCards(clubs){return clubs.length?clubs.map(c=>{const n=visibleInteractions().filter(i=>i.clubId===c.id).length;return `<div class="club-card" data-open-club="${c.id}"><div class="club-logo">${c.league}</div><div class="club-main"><div class="club-name">${esc(c.name)}</div><div class="club-meta">${c.league}</div></div><div class="club-count">${n} ${n===1?'interaction':'interactions'} →</div></div>`}).join(''):`<div class="empty">No clubs match your search.</div>`}
function clubOverview(club,interactions,plannedMeetings){
 const exl=new Map(),stakeholders=new Map();
 const add=(map,name,role='')=>{if(!name)return;const key=name.trim().toLowerCase();if(!map.has(key))map.set(key,{name:name.trim(),roles:new Set()});if(role)map.get(key).roles.add(role.trim())};
 interactions.forEach(i=>{const p=(i.participants||[]).find(x=>x.name===i.exlPoc)||(i.participants||[]).find(x=>(x.role||'').toLowerCase().includes('advisor'))||(i.participants||[])[0];add(exl,i.exlPoc||p?.name,p?.role);(i.stakeholders||[]).forEach(x=>add(stakeholders,x.name,x.role));if(!(i.stakeholders||[]).length)add(stakeholders,i.clubPoc,i.clubPocDesignation)});
 plannedMeetings.forEach(m=>{add(exl,m.exlPoc);add(stakeholders,m.clubPoc,m.clubPocDesignation)});
 const dates=[...new Set(interactions.map(i=>i.date).filter(Boolean))].sort((a,b)=>b.localeCompare(a));
 const next=plannedMeetings.filter(m=>m.date>=dt()).sort((a,b)=>a.date.localeCompare(b.date));
 const contactList=items=>items.length?`<div class="club-contact-list">${items.map(({name,roles})=>`<div class="club-contact"><span class="club-contact-avatar">${esc(initials(name))}</span><span><strong>${esc(name)}</strong>${roles.size?`<small>${[...roles].map(esc).join(' · ')}</small>`:''}</span></div>`).join('')}</div>`:'<div class="club-overview-empty">No contacts recorded yet.</div>';
 return `<section class="club-overview"><div class="club-overview-card exl-contact-card"><div class="club-overview-title"><div><strong>EXL point of contact</strong><small>${exl.size} ${exl.size===1?'person':'people'} across recorded meetings</small></div></div>${contactList([...exl.values()])}</div><div class="club-overview-card stakeholder-card"><div class="club-overview-title"><div><strong>Club stakeholders</strong><small>${stakeholders.size} ${stakeholders.size===1?'contact':'contacts'} recorded</small></div></div>${contactList([...stakeholders.values()])}</div><div class="club-overview-card dates-card"><div class="club-overview-title"><div><strong>Meeting dates</strong><span class="meeting-completed-count">${dates.length} completed</span></div></div>${dates.length?`<div class="meeting-date-chips">${dates.map(d=>`<span>${fmt(d)}</span>`).join('')}</div>`:'<div class="club-overview-empty">No completed meetings recorded yet.</div>'}</div><div class="club-overview-card next-meeting-card"><div class="club-overview-title"><div><strong>Next meeting</strong><small>Upcoming with this club</small></div></div>${next.length?`<div class="next-meeting-date">${fmt(next[0].date)}</div><div class="next-meeting-caption">${esc(next[0].meetingType||'Planned meeting')}${next[0].clubPoc?' with '+esc(next[0].clubPoc):''}${next[0].agenda?' · '+esc(next[0].agenda):''}</div>${next.length>1?`<span class="meeting-more">+ ${next.length-1} more planned</span>`:''}`:'<div class="club-overview-empty">▢ &nbsp; No upcoming meetings</div>'}</div></section>`
}
function clubInteractionCard(i){
 const stakeholders=(i.stakeholders||[]).length?i.stakeholders:[{name:i.clubPoc||'',role:i.clubPocDesignation||''}].filter(x=>x.name);
 const steps=i.followups||[];
 return `<article class="club-history-card"><header class="club-history-head"><span class="club-history-calendar">▦</span><div class="club-history-date"><small>MEETING DATE</small><strong>${fmt(i.date)}</strong></div>${i.sample?'<span class="pill sample-pill">Sample</span>':''}<div class="club-history-status">${nextStepPill(i)}</div></header><div class="club-history-contacts"><div class="club-history-contact exl-contact"><span class="contact-kicker">EXL POC</span><strong>${esc(exlPoc(i))}</strong></div><div class="club-history-contact stakeholder-contact"><span class="contact-kicker">CLUB STAKEHOLDERS</span><div class="stakeholder-name-list">${stakeholders.length?stakeholders.map(x=>`<span class="stakeholder-name"><strong>${esc(x.name)}</strong>${x.role?`<small>${esc(x.role)}</small>`:''}</span>`).join(''):'<span class="contact-missing">Not recorded</span>'}</div></div></div><div class="club-history-summary"><div class="club-history-label">Interaction summary</div><p>${esc(i.summary||'No discussion summary recorded.')}</p>${i.capabilities?.length?`<div class="club-history-label solution-label">Solutions discussed</div><div class="cap-list">${capsTags(i.capabilities,i.other)}</div>`:''}</div>${steps.length?`<div class="club-history-next"><div class="club-history-label">Next steps</div><div class="club-history-step-list">${steps.map(f=>`<div class="club-history-step"><div><strong>${esc(f.description)}</strong><small>Due ${fmt(f.due)} · ${esc(who(f.owner))}</small></div><span class="pill ${f.status==='Open'?'orange':f.status==='Done'?'green':'red'}">${esc(f.status)}</span></div>`).join('')}</div></div>`:''}</article>`
}
function clubPage(){
 const c=clubBy(selectedClub);if(!c||!canSeeClub(c.id)){page='clubs';return clubsPage()}
 const ix=visibleInteractions().filter(i=>i.clubId===c.id).sort((a,b)=>b.date.localeCompare(a.date));
 const meetings=visibleMeetings().filter(m=>m.clubId===c.id).sort((a,b)=>a.date.localeCompare(b.date));
 const fs=allFollowups().filter(f=>f.club?.id===c.id&&f.status==='Open').sort((a,b)=>a.due.localeCompare(b.due));
 const body=clubTab==='history'
  ? `<div class="club-history-list">${ix.length?ix.map(clubInteractionCard).join(''):'<div class="empty"><div class="empty-icon">◉</div>No interactions for this club yet.</div>'}</div>`
  : clubTab==='meetings'
   ? `<div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Participants & agenda</th><th>Owner</th><th>Actions</th></tr></thead><tbody>${meetings.length?meetings.map(m=>`<tr><td>${fmt(m.date)}</td><td><div class="cell-title">${esc(m.meetingType||'Meeting')} ${m.sample?'<span class="pill sample-pill">Sample</span>':''} · ${esc(m.clubPoc||'Club/client POC TBD')}</div><div class="cell-sub">EXL POC: ${esc(m.exlPoc||'TBD')}${m.clubPocDesignation?' · '+esc(m.clubPocDesignation):''} · ${esc(m.agenda||'No agenda')}</div></td><td>${esc(who(m.owner))}</td><td>${meetingActions(m)}</td></tr>`).join(''):`<tr><td colspan="4"><div class="empty">No meetings planned.</div></td></tr>`}</tbody></table></div>`
   : `<div class="table-wrap"><table class="table"><thead><tr><th>Next step</th><th>Owner</th><th>Due</th><th>Status</th><th></th></tr></thead><tbody>${fs.length?fs.map(f=>`<tr><td><div class="cell-title">${esc(f.description)}</div></td><td>${esc(who(f.owner))}</td><td>${fmt(f.due)} ${f.due<dt()?'<span class="pill red">Overdue</span>':''}</td><td><span class="pill orange">Open</span></td><td>${followupCanEdit(f)?`<button class="action-link" data-follow-status="${f.id}" data-next="Done">Mark done</button>`:''}</td></tr>`).join(''):`<tr><td colspan="5"><div class="empty">No open next steps.</div></td></tr>`}</tbody></table></div>`;
 return `${head('CLUB RELATIONSHIP',esc(c.name),`${c.league} · ${ix.length} completed ${ix.length===1?'interaction':'interactions'}`,`<button class="btn" data-page="clubs">← &nbsp; All clubs</button>${isAdmin()?'':`<button class="btn primary" data-log-club="${c.id}">＋ &nbsp; Log interaction</button>`}`)}<div class="card"><div class="club-hero"><div class="club-logo">${c.league}</div><div><div class="club-hero-name">${esc(c.name)}</div><div class="club-meta">${c.league} · Shared across advisors and POCs</div></div></div>${clubOverview(c,ix,meetings)}<div class="club-tabs"><button class="club-tab ${clubTab==='history'?'active':''}" data-tab="history">Interaction history (${ix.length})</button><button class="club-tab ${clubTab==='meetings'?'active':''}" data-tab="meetings">Planned meetings (${meetings.length})</button><button class="club-tab ${clubTab==='followups'?'active':''}" data-tab="followups">Next steps (${fs.length})</button></div><div id="club-tab-body">${body}</div></div><div class="detail-columns"><section class="card relationship-snapshot"><div class="card-head"><div><div class="card-title">Relationship snapshot</div><div class="card-sub">A quick summary of this club relationship</div></div><span class="snapshot-mark">◈</span></div><div class="snapshot-metrics"><div class="snapshot-metric"><small>COMPLETED INTERACTIONS</small><strong>${ix.length}</strong><span>${ix.length===1?'interaction recorded':'interactions recorded'}</span></div><div class="snapshot-metric"><small>FIRST MET</small><strong>${ix.length?fmt(ix.reduce((earliest,x)=>x.date<earliest.date?x:earliest,ix[0]).date,{month:'short',day:'numeric',year:'numeric'}):'—'}</strong><span>${ix.length?'Earliest recorded interaction':'No meetings recorded yet'}</span></div><div class="snapshot-metric"><small>OPEN NEXT STEPS</small><strong>${fs.length}</strong><span>${fs.filter(f=>f.due<dt()).length} overdue</span></div></div><div class="snapshot-status-row"><div><small>CURRENT OVERALL STATUS</small><div>${ix.length?nextStepPill(ix[0]):'<span class="next-step-tag">Not set</span>'}</div></div><div class="snapshot-capabilities"><small>MOST DISCUSSED CAPABILITIES</small><div class="cap-list">${(()=>{const counts={};ix.forEach(x=>(x.capabilities||[]).filter(cap=>cap!=='Other').forEach(cap=>counts[cap]=(counts[cap]||0)+1));return Object.entries(counts).sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0])).slice(0,3).map(([cap,n])=>`<span class="snapshot-capability">${esc(cap)} <b>${n}</b></span>`).join('')||'<span class="snapshot-empty">No capabilities recorded yet</span>'} )()}</div></div></div></section><section class="card"><div class="card-head"><div><div class="card-title">Next steps</div><div class="card-sub">Meetings and actions to keep moving</div></div></div><div class="card-body">${meetings.slice(0,2).map(meetingCard).join('')}${fs.slice(0,2).map(taskCard).join('')||(!meetings.length?'<div class="empty">Nothing upcoming.</div>':'')}</div></section></div>`
}
function historyPreview(id){const c=clubBy(id);if(!c)return '';const history=visibleInteractions().filter(x=>x.clubId===id).sort((a,b)=>b.date.localeCompare(a.date));if(!history.length)return `<div class="note" style="margin:0 0 14px">No previous interactions for ${esc(c.name)} yet.</div>`;return `<div class="card" style="margin-bottom:14px"><div class="card-head"><div><div class="card-title">${esc(c.name)} · recent history</div><div class="card-sub">${history.length} previous ${history.length===1?'interaction':'interactions'} available while you prepare</div></div><button type="button" class="link-btn" data-open-club="${c.id}">Open club →</button></div><div class="card-body">${history.slice(0,2).map(x=>`<div class="activity-row"><div class="league-mark">${c.league}</div><div><div class="activity-club">${fmt(x.date)}</div><div class="activity-summary">${esc(x.summary)}</div><div class="cap-list">${capsTags(x.capabilities,x.other)}</div></div></div>`).join('')}</div></div>`}
function interactionForm(prefill=''){
 const clubs=visibleClubs().slice().sort((a,b)=>a.name.localeCompare(b.name)),i=editingInteraction,scheduled=meetingToComplete?db.meetings.find(m=>m.id===meetingToComplete):null,planned=null,cId=prefill||i?.clubId||scheduled?.clubId||'';
 const stakeholder=(i?.stakeholders||[])[0]||{},participant=(i?.participants||[])[0]||{};
 const clientName=i?.clubPoc||stakeholder.name||scheduled?.clubPoc||'',clientRole=i?.clubPocDesignation||stakeholder.role||scheduled?.clubPocDesignation||'';
 const exlName=i?.exlPoc||participant.name||scheduled?.exlPoc||user().name;
 const followups=i?.followups||[{description:'',owner:user().id,due:'',status:'Open'}];
 const clubOptions=clubs.map(c=>'<option value="'+c.id+'" '+(c.id===cId?'selected':'')+'>'+esc(c.name)+' · '+c.league+'</option>').join('');
 const capOptions=CAPS.map(c=>'<label class="check-option"><input type="checkbox" name="capability" value="'+esc(c)+'" '+((i?.capabilities||[]).includes(c)?'checked':'')+'>'+esc(c)+'</label>').join('');
 const nextOptions=NEXT_STEP_TYPES.map(x=>'<option '+((i?.nextStepType||'Yet to be decided')===x?'selected':'')+'>'+esc(x)+'</option>').join('');
 const isEdit=!!i||!!planned;
 return head(i?'EDIT INTERACTION':planned?'COMPLETE PLANNED MEETING':'CAPTURE THE CONVERSATION',i?'Update interaction':planned?'Complete planned meeting':'Log an interaction','Record a completed conversation or schedule a future meeting.', '<button class="btn" data-page="clubs">Cancel</button>')
 +'<div class="form-wrap"><div id="club-history-slot">'+historyPreview(cId)+'</div><form class="card form-card" id="interaction-form">'
 +'<div class="form-section"><h3 class="form-section-title">01 &nbsp; Meeting details</h3><div class="form-grid">'
 +(!isEdit?'<div class="field"><label>What are you recording? *</label><select class="select" name="recordMode" id="record-mode"><option value="interaction">Completed interaction</option><option value="planned">Plan a meeting</option></select></div>':'')
 +'<div class="field"><label>Club *</label><select class="select" name="clubId" required><option value="">Select a club</option>'+clubOptions+'</select></div><div class="field"><label id="date-label">'+(planned?'Meeting date *':'Interaction date *')+'</label><input class="input" name="date" type="date" value="'+(i?.date||scheduled?.date||dt())+'" required></div><div class="field" id="planned-time-wrap" style="'+(planned?'':'display:none')+'"><label>Meeting time</label><input class="input" name="meetingTime" type="time" value="'+(scheduled?.time||'')+'"></div>'
 +'<div class="field" id="meeting-type-wrap" style="'+(planned?'':'display:none')+'"><label>Meeting type *</label><select class="select" name="meetingType" id="meeting-type"><option value="First meeting" '+((planned?.meetingType||'First meeting')==='First meeting'?'selected':'')+'>First meeting</option><option value="Follow-up meeting" '+(planned?.meetingType==='Follow-up meeting'?'selected':'')+'>Follow-up meeting</option></select></div>'
 +'<div class="field full"><label>EXL POC *</label><div id="participant-rows"><div class="attendee-row poc-single"><input class="mini-input" name="participantName" placeholder="EXL point of contact" value="'+esc(exlName)+'" required><input type="hidden" name="participantRole" value="EXL POC"></div></div></div>'
 +'<div class="field full"><label>Club/client POC *</label><div id="stakeholder-rows"><div class="attendee-row poc-pair"><input class="mini-input" name="stakeholderName" placeholder="Club/client point of contact" value="'+esc(clientName)+'" required><input class="mini-input" name="stakeholderRole" placeholder="Designation" value="'+esc(clientRole)+'" required></div></div></div>'
 +'<div class="field full"><label id="summary-label">'+(planned?'Meeting description / agenda *':'Discussion summary *')+'</label><textarea class="textarea" name="summary" required placeholder="'+(planned?'Describe the introductory meeting and what you plan to discuss.':'What did you discuss?')+'">'+esc(i?.summary||scheduled?.agenda||'')+'</textarea></div><div class="field full note" id="planned-hint" style="'+(planned?'':'display:none')+'">This saves an upcoming meeting only. It will not appear as a completed interaction until you mark it complete.</div></div></div>'
 +'<div id="completed-only-fields" style="'+(planned?'display:none':'')+'"><div class="form-section"><h3 class="form-section-title">02 &nbsp; Capabilities discussed</h3><div class="check-grid">'+capOptions+'</div><div class="field" id="other-field" style="margin-top:10px;'+((i?.capabilities||[]).includes('Other')?'':'display:none')+'"><label>What else was discussed?</label><input class="input" name="other" placeholder="Add a capability or topic" value="'+esc(i?.other||'')+'"></div></div>'
 +'<div class="form-section"><h3 class="form-section-title">03 &nbsp; Overall status and next meeting</h3><div class="form-grid"><div class="field"><label>Overall status *</label><select class="select" name="nextStepType" required>'+nextOptions+'</select></div><div class="field"><label>Next meeting date</label><input class="input" type="date" name="nextMeeting" value="'+(i?.nextMeeting||'')+'"></div><div class="field"><label>Meeting time</label><input class="input" type="time" name="nextMeetingTime" value="'+(i?.nextMeetingTime||'')+'"></div><div class="field full"><label>Next meeting agenda (optional)</label><input class="input" name="nextAgenda" value="'+esc(i?.nextAgenda||'')+'" placeholder="Topic for the next conversation"></div></div><p class="hint">A meeting date creates a planned meeting, not a completed interaction.</p></div>'
 +'<div class="form-section"><h3 class="form-section-title">04 &nbsp; Next steps</h3><span class="hint">Add specific actions with an owner and due date.</span><div id="followup-rows" style="margin-top:10px">'+followups.map(f=>followRow(f)).join('')+'</div><button type="button" class="btn small" data-add-row="followup">＋ Add next step</button></div></div>'
 +'<div class="form-actions"><button type="button" class="btn" data-page="clubs">Cancel</button><button class="btn primary" type="submit">'+(i?'Save changes':planned?'Save interaction':'<span id="submit-label">Save interaction</span>')+' &nbsp; →</button></div></form></div>';
}
function syncInteractionMode(){const planned=$('#record-mode')?.value==='planned';const fields=$('#completed-only-fields'),type=$('#meeting-type-wrap'),time=$('#planned-time-wrap'),date=$('[name=date]'),meetingType=$('#meeting-type'),summary=$('[name=summary]');if(fields){fields.style.display=planned?'none':'';fields.querySelectorAll('input,select,textarea,button').forEach(x=>x.disabled=planned)}if(type)type.style.display=planned?'grid':'none';if(time)time.style.display=planned?'grid':'none';if(date)date.previousElementSibling.textContent=planned?'Meeting date *':'Interaction date *';if(meetingType)meetingType.required=planned;if(summary){summary.previousElementSibling.textContent=planned?'Meeting description / agenda *':'Discussion summary *';summary.placeholder=planned?'Describe the introductory meeting and what you plan to discuss.':'What did you discuss?'}const hint=$('#planned-hint');if(hint)hint.style.display=planned?'block':'none';const submit=$('#submit-label');if(submit)submit.textContent=planned?'Save planned meeting':'Save interaction'}
function attendeeRow(a,kind){return `<div class="attendee-row"><input class="mini-input" name="${kind}Name" placeholder="Name" value="${esc(a.name)}"><input class="mini-input" name="${kind}Role" placeholder="Role" value="${esc(a.role)}"><button type="button" class="action-link" data-remove-row>×</button></div>`}
function followRow(f){return `<div class="follow-row"><input class="mini-input" name="followDescription" placeholder="Action description" value="${esc(f.description)}"><select class="mini-input" name="followOwner">${db.users.map(u=>`<option value="${u.id}" ${u.id===f.owner?'selected':''}>${esc(u.name)}</option>`).join('')}</select><input class="mini-input" type="date" name="followDue" value="${f.due||''}"><select class="mini-input" name="followStatus">${['Open','Done','Canceled'].map(s=>`<option ${f.status===s?'selected':''}>${s}</option>`).join('')}</select><button type="button" class="action-link" data-remove-row>×</button></div>`}
function meetingActions(m){if(!isAdmin()&&m.owner!==user().id)return '';return '<button class="action-link" data-meeting-edit="'+m.id+'">Edit</button>'+(isAdmin()?'':'<button class="action-link" data-meeting-complete="'+m.id+'">Complete</button>')+'<button class="action-link" data-meeting-cancel="'+m.id+'">Cancel</button>'}
function localDateKey(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function meetingTimeLabel(value){if(!value)return 'Time not set';const [hour,minute]=value.split(':').map(Number);return new Date(2000,0,1,hour,minute||0).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'})}
function meetingSteps(meeting){const interaction=visibleInteractions().find(i=>i.id===meeting.interactionId||i.meetingId===meeting.id);return (interaction?.followups||[]).filter(f=>f.status==='Open').map(f=>({...f,interaction,club:clubBy(interaction.clubId)}))}
function calendarMeetingPanel(meetings){return meetings.length?meetings.map(m=>{const steps=meetingSteps(m);return `<article class="calendar-detail-meeting"><div class="calendar-detail-top"><div><strong>${esc(clubShort(clubBy(m.clubId)))}</strong><span>${esc(meetingTimeLabel(m.time))}</span></div></div><div class="calendar-detail-steps"><small>NEXT STEPS</small>${steps.length?steps.map(f=>`<div class="calendar-detail-step">${esc(f.description)}</div>`).join(''):'<div class="calendar-no-steps">No open next steps for this club.</div>'}</div></article>`}).join(''):'<div class="calendar-empty-day"><span>◷</span><strong>No meetings scheduled</strong><small>Select another date to review its meetings.</small></div>'}
function calendarMarkup(){
 const year=calendarMonth.getFullYear(),month=calendarMonth.getMonth(),start=new Date(year,month,1),offset=(start.getDay()+6)%7,total=new Date(year,month+1,0).getDate(),slots=Math.ceil((offset+total)/7)*7;
 const meetings=visibleMeetings().filter(m=>m.date.slice(0,7)===`${year}-${String(month+1).padStart(2,'0')}`).sort((a,b)=>a.time.localeCompare(b.time));
 const days=Array.from({length:slots},(_,n)=>{const number=n-offset+1;if(number<1||number>total)return '<div class="calendar-day outside"></div>';const date=localDateKey(new Date(year,month,number)),items=meetings.filter(m=>m.date===date),events=items.slice(0,3).map(m=>`<span class="calendar-event"><b>${esc(clubShort(clubBy(m.clubId)))}</b><small>${esc(meetingTimeLabel(m.time))}</small></span>`).join('');return `<button type="button" class="calendar-day ${date===selectedCalendarDate?'selected':''} ${date===dt()?'today':''}" data-calendar-date="${date}"><span class="calendar-day-number">${number}</span><span class="calendar-day-events">${events}${items.length>3?`<small class="calendar-more">+${items.length-3} more</small>`:''}</span></button>`}).join('');
 const selected=visibleMeetings().filter(m=>m.date===selectedCalendarDate).sort((a,b)=>a.time.localeCompare(b.time));
 return `<section class="card follow-calendar-card"><div class="card-head calendar-heading"><div><div class="card-title">Meeting calendar</div><div class="card-sub">Scheduled club meetings and their open next steps</div></div><div class="calendar-month-switch"><button type="button" class="btn small" data-calendar-shift="-1" aria-label="Previous month">‹</button><strong>${start.toLocaleDateString('en-US',{month:'long',year:'numeric'})}</strong><button type="button" class="btn small" data-calendar-shift="1" aria-label="Next month">›</button></div></div><div class="calendar-layout"><div class="calendar-main"><div class="calendar-weekdays">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<span>${d}</span>`).join('')}</div><div class="calendar-grid">${days}</div></div><aside class="calendar-day-panel"><div class="calendar-selected-date"><small>SELECTED DAY</small><strong>${fmt(selectedCalendarDate,{weekday:'long',month:'short',day:'numeric',year:'numeric'})}</strong></div><div class="calendar-selected-list">${calendarMeetingPanel(selected)}</div></aside></div></section>`
}
function followupsPage(){
 const all=allFollowups(),open=all.filter(f=>f.status==='Open'),today=dt(),now=new Date(),monthStart=localDateKey(new Date(now.getFullYear(),now.getMonth(),1)),monthEnd=localDateKey(new Date(now.getFullYear(),now.getMonth()+1,0));
 const week=open.filter(f=>f.due>=today&&f.due<=dt(7)),month=open.filter(f=>f.due>=today&&f.due<=monthEnd),overdue=open.filter(f=>f.due<today);
 const owned=open.filter(f=>f.owner===user().id||f.interaction.owner===user().id),admin=isAdmin();
 const ranges=[['open','Open next steps','All open actions',admin?open.length:owned.length,'✓'],['week','Due this week','Today through next 7 days',week.length,'◷'],['month','Due this month',fmt(monthStart,{month:'short',day:'numeric'})+' – '+fmt(monthEnd,{month:'short',day:'numeric'}),month.length,'▦'],['overdue','Overdue','Past due date',overdue.length,'!']];
 const selectedStatus=$('#follow-status-filter')?.value||'Open';
 let rows=all.filter(f=>selectedStatus==='all'||f.status===selectedStatus);
 if(followupRange==='open')rows=all.filter(f=>f.status==='Open');
 if(followupRange==='week')rows=week;
 if(followupRange==='month')rows=month;
 if(followupRange==='overdue')rows=overdue;
 rows.sort((a,b)=>a.due.localeCompare(b.due));
 const ownedRows=admin?rows.length:rows.filter(f=>f.owner===user().id||f.interaction.owner===user().id).length;
 return `${head(admin?'TEAM FOLLOW-THROUGH':'NEXT STEPS',admin?'Next steps summary':'My next steps',admin?'Review next steps across advisors and EXL POCs, and see the meetings they support.':'Keep commitments visible and see the meetings they support.','<button class="btn" data-page="digest">◷ &nbsp; Overview</button>')}<div class="followup-summary-tabs">${ranges.map(([key,label,note,count,ico])=>`<button type="button" class="followup-summary-tab ${followupRange===key?'active':''}" data-followup-range="${key}"><span class="followup-summary-icon">${ico}</span><span class="followup-summary-copy"><small>${label}</small><strong>${count}</strong><em>${note}</em></span></button>`).join('')}</div>${calendarMarkup()}<div class="card followup-table-card"><div class="card-head"><div><div class="card-title">${admin?'All next steps':'My next steps'}</div><div class="card-sub">${followupRange==='open'?'Open next steps across clubs':followupRange==='week'?'Open actions due this week':followupRange==='month'?'Open actions due this month':followupRange==='overdue'?'Open actions past due':'Actions across the selected status'} · ${ownedRows} shown</div></div><select class="select" id="follow-status-filter"><option value="Open" ${selectedStatus==='Open'?'selected':''}>Open</option><option value="all" ${selectedStatus==='all'?'selected':''}>All statuses</option><option value="Done" ${selectedStatus==='Done'?'selected':''}>Done</option><option value="Canceled" ${selectedStatus==='Canceled'?'selected':''}>Canceled</option></select></div><div class="table-wrap"><table class="table"><thead><tr><th>Next step</th><th>Club</th><th>Owner</th><th>Due date</th><th>Status</th><th></th></tr></thead><tbody id="follow-table">${followRows(rows)}</tbody></table></div></div>`
}
function followRows(rows){return rows.length?rows.map(f=>`<tr><td><div class="cell-title">${esc(f.description)}</div><div class="cell-sub">From ${fmt(f.interaction.date)} interaction</div></td><td><button class="action-link" data-open-club="${f.club?.id}">${esc(clubShort(f.club))}</button></td><td>${esc(who(f.owner))}</td><td>${fmt(f.due)} ${f.due<dt()&&f.status==='Open'?'<span class="pill red">Overdue</span>':''}</td><td><span class="pill ${f.status==='Open'?'orange':f.status==='Done'?'green':'red'}">${f.status}</span></td><td>${f.status==='Open'&&followupCanEdit(f)?`<button class="action-link" data-follow-status="${f.id}" data-next="Done">Mark done</button><button class="action-link" data-follow-status="${f.id}" data-next="Canceled">Cancel</button>`:''}</td></tr>`).join(''):`<tr><td colspan="6"><div class="empty"><div class="empty-icon">✓</div>No next steps in this view.</div></td></tr>`}
function followupCanEdit(f){return isAdmin()||f.owner===user().id||f.interaction.owner===user().id}
function digestPage(){
 const today=dt(),monthStart=new Date();monthStart.setDate(1);const start=monthStart.toISOString().slice(0,10);
 const ix=visibleInteractions();
 const from=$('#digest-from')?.value||start,to=$('#digest-to')?.value||today;
 const league=$('#digest-league')?.value||'all',club=$('#digest-club')?.value||'all',advisor=$('#digest-advisor')?.value||'all',poc=$('#digest-poc')?.value||'all',cap=$('#digest-cap')?.value||'all',status=$('#digest-status')?.value||'all',nextType=$('#digest-next-step')?.value||'all';
 const filtered=ix.filter(i=>{const c=clubBy(i.clubId);return i.date>=from&&i.date<=to&&(club==='all'||i.clubId===club)&&(league==='all'||c?.league===league)&&(advisor==='all'||i.participants.some(p=>p.role.toLowerCase().includes('advisor')&&p.name===who(advisor))||i.owner===advisor)&&(poc==='all'||i.participants.some(p=>p.role.toLowerCase().includes('poc')&&p.name===who(poc))||i.owner===poc)&&(cap==='all'||i.capabilities.includes(cap))&&(status==='all'||i.followups.some(f=>f.status===status))&&(nextType==='all'||(i.nextStepType||'Yet to be decided')===nextType)});
 const meetings=visibleMeetings().filter(m=>m.date>=today).sort((a,b)=>a.date.localeCompare(b.date));
 const dateField=(label,id,value)=>'<label class="filter-field"><span>'+label+'</span><input class="input" type="date" id="'+id+'" value="'+value+'"></label>';
 const selectField=(label,id,options,value)=>'<label class="filter-field"><span>'+label+'</span><select class="select" id="'+id+'">'+options.map(o=>'<option value="'+esc(o.value)+'" '+(o.value===value?'selected':'')+'>'+esc(o.label)+'</option>').join('')+'</select></label>';
 const leagueOptions=[{value:'all',label:'All leagues'},...Object.keys(LEAGUES).map(x=>({value:x,label:x}))];
 const clubOptions=[{value:'all',label:'All clubs'},...visibleClubs().map(c=>({value:c.id,label:c.name}))];
 const userOptions=[{value:'all',label:'All users'},...db.users.filter(u=>u.role==='User').map(u=>({value:u.id,label:u.name}))];
 const capOptions=[{value:'all',label:'All capabilities'},...CAPS.map(x=>({value:x,label:x}))];
 const statusOptions=[{value:'all',label:'All next-step statuses'},...['Open','Done','Canceled'].map(x=>({value:x,label:x}))];
 const nextOptions=[{value:'all',label:'All next-step tags'},...NEXT_STEP_TYPES.map(x=>({value:x,label:x}))];
 const actions='<button class="btn" id="clear-digest">Reset filters</button>'+(isAdmin()?'':'<button class="btn primary" data-page="log">＋ &nbsp; Log interaction</button>');
 const groups=isAdmin()?'<div class="segmented"><button class="active" type="button">All users</button><button data-group="advisor">By advisor</button><button data-group="poc">By EXL POC</button></div>':'';
 activeDigestItems=filtered;
 return head('RELATIONSHIP ACTIVITY','Overview','Completed conversations, upcoming meetings, and follow-through in one place.',actions)
 +'<section class="card upcoming-top"><div class="card-head"><div><div class="card-title">Upcoming meetings</div><div class="card-sub">Your next scheduled conversations</div></div><span class="count-badge">'+meetings.length+'</span></div><div class="upcoming-strip">'+(meetings.length?meetings.slice(0,4).map(meetingCard).join(''):'<div class="empty">No upcoming meetings are scheduled.</div>')+'</div></section>'
 +'<section class="card filter-panel"><div class="filter-panel-title"><div><div class="card-title">Activity filters</div><div class="card-sub">Choose a date range and narrow the activity below</div></div><span class="filter-panel-icon">⌕</span></div><div class="digest-controls">'
 +dateField('From date','digest-from',from)+dateField('To date','digest-to',to)
 +selectField('League','digest-league',leagueOptions,league)+selectField('Club','digest-club',clubOptions,club)
 +selectField('Advisor','digest-advisor',userOptions,advisor)+selectField('EXL POC','digest-poc',userOptions,poc)
 +selectField('Capability','digest-cap',capOptions,cap)+selectField('Action status','digest-status',statusOptions,status)+selectField('Overall status','digest-next-step',nextOptions,nextType)
 +'</div></section>'
 +'<section class="overview-section"><div class="overview-section-heading"><div><div class="greeting">ACTIVITY SNAPSHOT</div><h2>Overview</h2><p>'+esc(fmt(from,{month:'short',day:'numeric',year:'numeric'}))+' – '+esc(fmt(to,{month:'short',day:'numeric',year:'numeric'}))+'</p></div></div>'
 +'<div class="stats-grid overview-stat-grid">'+stat('Completed interactions','In selected date range',filtered.length,'◉')+stat('Unique clubs','With interactions',new Set(filtered.map(i=>i.clubId)).size,'▦')+stat('Upcoming meetings','Planned from today',meetings.length,'◷')+'</div>'
 +'<section class="card"><div class="card-head"><div><div class="card-title">Interaction activity</div><div class="card-sub">Club/client and EXL points of contact, discussion, overall status, and next steps</div></div>'+groups+'</div><div class="digest-list" id="digest-results">'+digestRows(filtered)+'</div></section></section>'+overviewSupport();
}
function overviewSupport(){const tasks=allFollowups().filter(f=>f.status==='Open').sort((a,b)=>a.due.localeCompare(b.due)).slice(0,4);return '<div class="overview-support"><section class="card"><div class="card-head"><div><div class="card-title">Next steps</div><div class="card-sub">Specific actions, sorted by due date</div></div><button class="link-btn" data-page="followups">All next steps →</button></div><div class="card-body">'+(tasks.length?tasks.map(taskCard).join(''):'<div class="empty">No open next steps.</div>')+'</div></section></div>'}
function digestRows(ix){
 if(!ix.length)return '<div class="empty"><div class="empty-icon">◷</div>No interactions match these filters.</div>';
 return ix.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(i=>{
  const c=clubBy(i.clubId),steps=i.followups||[];
  const stepRows=steps.length?steps.map(f=>{
   const overdue=f.status==='Open'&&f.due<dt();
   const state=overdue?'<span class="pill red">Overdue</span>':'<span class="pill '+(f.status==='Done'?'green':f.status==='Canceled'?'red':'orange')+'">'+esc(f.status)+'</span>';
   return '<div class="next-action-row"><div class="next-action-copy"><div class="next-action-title">'+esc(f.description)+'</div><div class="next-action-meta">Owner: '+esc(who(f.owner))+' <span>·</span> Due: '+fmt(f.due)+'</div></div>'+state+'</div>';
  }).join(''):'<div class="next-action-empty">No individual actions recorded.</div>';
  return '<article class="digest-item interaction-record">'
   +'<header class="interaction-record-head"><div class="interaction-record-club"><div class="league-mark">'+(c?.league||'—')+'</div><div><div class="activity-club">'+esc(clubShort(c))+' '+leagueTag(c?.league||'')+(i.sample?' <span class="pill sample-pill">Sample</span>':'')+'</div><div class="activity-meta">'+fmt(i.date)+'</div></div></div><button class="action-link" data-open-club="'+i.clubId+'">Club history →</button></header>'
   +'<div class="interaction-pocs"><div class="interaction-poc"><span class="poc-label">EXL POC</span><strong>'+esc(exlPoc(i))+'</strong></div><div class="poc-divider"></div><div class="interaction-poc"><span class="poc-label">Club/client POC</span><strong>'+esc(clubPoc(i))+'</strong><span class="poc-designation">'+esc(clubPocDesignation(i))+'</span></div></div>'
   +'<div class="interaction-record-body"><section class="interaction-discussion"><div class="interaction-section-label"><span class="section-icon">◌</span>Discussion summary</div><p>'+esc(i.summary)+'</p><div class="interaction-section-label capability-heading">Solutions discussed</div><div class="cap-list">'+capsTags(i.capabilities,i.other)+'</div></section>'
   +'<aside class="interaction-next-panel"><div class="interaction-next-head"><div><div class="next-kicker">ACTION PLAN</div><h3>Next steps</h3></div><div class="overall-status"><span>Overall status</span>'+nextStepPill(i)+'</div></div><div class="next-action-list">'+stepRows+'</div></aside></div></article>';
 }).join('');
}
function contractDashboard(u,c){
 const stat=(label,value,note='')=>`<div class="contract-kpi"><small>${label}</small><strong>${value}</strong>${note?`<span>${note}</span>`:''}</div>`;
 const detail=(label,value)=>`<div class="contract-detail"><span>${label}</span><strong>${esc(value||'Not set')}</strong></div>`;
 const pct=Math.max(0,Math.min(100,Math.round((Number(c.hoursUsed||0)/Math.max(1,Number(c.hoursCap||1)))*100)));
 const deliverables=(c.deliverables||[]).map(x=>{const progress=Math.max(0,Math.min(100,Math.round(Number(x.actual||0)/Math.max(1,Number(x.target||1))*100)));return `<div class="contract-progress-row"><div class="contract-progress-copy"><strong>${esc(x.name)}</strong><span>${esc(x.actual)} of ${esc(x.target)} · ${progress}%</span></div><div class="contract-progress-track"><i style="width:${progress}%"></i></div></div>`}).join('');
 const compliance=(c.compliance||[]).map(x=>`<div class="contract-check-row"><div><strong>${esc(x.name)}</strong><small>${esc(x.detail||'')}</small></div><span class="pill ${x.status==='Complete'?'green':x.status==='In progress'?'orange':'blue'}">${esc(x.status)}</span></div>`).join('');
 return `<div class="contract-dashboard"><section class="contract-kpis">${stat('HOURLY RATE',`${contractMoney(c.hourlyRate)} / hr`)}${stat('MONTHLY CAP',`${esc(c.monthlyCap)} hrs`,`${contractMoney(Number(c.monthlyCap||0)*Number(c.hourlyRate||0))} cap value`)}${stat('TERM ENDS',fmt(c.sowEnd))}${stat('EXTENSION DEADLINE',fmt(c.extensionDeadline))}</section><div class="contract-dashboard-grid"><section class="card contract-dash-card"><div class="contract-section-head"><div><h2>Contract summary</h2><p>Who, when, and under what terms</p></div></div><div class="contract-detail-grid">${detail('Advisor / POC',u.name)}${detail('Role',c.role||u.title)}${detail('EXL contact',c.exlContact)}${detail('Agreement date',fmt(c.agreementDate))}${detail('SOW start',fmt(c.sowStart))}${detail('SOW end',fmt(c.sowEnd))}${detail('Location',c.location)}${detail('Governing law',c.governingLaw)}${detail('Payment terms',c.paymentTerms)}</div></section><section class="card contract-dash-card"><div class="contract-section-head"><div><h2>Key dates & deadlines</h2><p>Term milestones and commission window</p></div></div><div class="contract-timeline"><div><b>${fmt(c.sowStart)}</b><strong>Term begins</strong><small>Work and billing start</small></div><div><b>${fmt(c.extensionDeadline)}</b><strong>Extension deadline</strong><small>Written extension due</small></div><div><b>${fmt(c.sowEnd)}</b><strong>Term ends</strong><small>Six-month cap or SOW completion</small></div><div><b>${fmt(c.commissionWindowEnd)}</b><strong>Commission window closes</strong><small>Eligibility window closes</small></div></div><div class="contract-callout"><b>Recurring:</b> Timesheet due on the last day of each month → approval → invoice → payment within 30 days. Insurance must remain current through the term.</div></section><section class="card contract-dash-card"><div class="contract-section-head"><div><h2>Compensation</h2><p>Hourly retainer and expense rules</p></div></div><div class="contract-term-list">${detail('Hourly rate',`${contractMoney(c.hourlyRate)} / hr`)}${detail('Cap — first month',`${c.firstMonthCap} hrs (${contractMoney(Number(c.firstMonthCap||0)*Number(c.hourlyRate||0))})`)}${detail('Cap — each month after',`${c.monthlyCap} hrs (${contractMoney(Number(c.monthlyCap||0)*Number(c.hourlyRate||0))})`)}${detail('Extra hours',c.extraHours)}${detail('Timesheet due','Last day of month')}${detail('Payment terms',c.paymentTerms)}${detail('Travel & expenses',c.travelExpenses)}${detail('One-time incentive',`${contractMoney(c.oneTimeIncentive)} · first SOW in a new buying center`)}</div><div class="contract-usage"><div><strong>Hours used this month</strong><span>${esc(c.hoursUsed)} of ${esc(c.hoursCap)} hrs (${pct}%)</span></div><div class="contract-progress-track"><i style="width:${pct}%"></i></div></div></section><section class="card contract-dash-card"><div class="contract-section-head"><div><h2>New business commission</h2><p>Commission terms</p></div></div><div class="contract-commission-table"><div class="contract-commission-row heading"><span>TRIGGER</span><span>COMMISSION</span></div><div class="contract-commission-row"><span>New MSA · annual revenue above ${contractMoney(Number(c.largeMsaThreshold||0)*1000000)}</span><strong>${contractMoney(c.largeMsaCommission)}</strong></div><div class="contract-commission-row"><span>New MSA · other prospects</span><strong>${contractMoney(c.otherMsaCommission)}</strong></div><div class="contract-commission-row"><span>New SOW · months 1–12</span><strong>${esc(c.sowYearOnePercent)}% of revenue</strong></div><div class="contract-commission-row"><span>New SOW · months 13–24</span><strong>${esc(c.sowYearTwoPercent)}% of revenue</strong></div><div class="contract-commission-row"><span>First SOW in a new buying center</span><strong>${contractMoney(c.oneTimeIncentive)}</strong></div></div><div class="contract-callout">Commission eligibility depends on the signed agreement and approval process. Salesforce remains the source of truth for opportunities.</div></section><section class="card contract-dash-card"><div class="contract-section-head"><div><h2>Deliverables — target vs. actual</h2><p>Commitments for the full term</p></div></div><div class="contract-deliverables">${deliverables||'<div class="empty">No deliverables recorded.</div>'}</div></section><section class="card contract-dash-card"><div class="contract-section-head"><div><h2>Compliance & onboarding</h2><p>Must be completed before work starts and kept current</p></div></div><div class="contract-checklist">${compliance||'<div class="empty">No checklist items recorded.</div>'}</div></section><section class="card contract-dash-card contract-wide"><div class="contract-section-head"><div><h2>Scope, conditions & restrictions</h2><p>Responsibilities and continuing obligations</p></div></div><div class="contract-obligations"><div><small>SCOPE OF WORK</small><p>${esc(c.scope)}</p></div><div><small>TERMS & CONDITIONS</small><p>${esc(c.conditions)}</p></div><div><small>RESTRICTIONS & POST-EXIT OBLIGATIONS</small><p>${esc(c.restrictions)}</p></div></div></section></div></div>`
}
function contractEditorForm(u){
 const c=contractFor(u.id),input=(label,key,type='text',step='')=>`<label class="contract-edit-field"><span>${label}</span><input class="input" name="${key}" type="${type}" value="${esc(c[key])}" ${type==='number'?`min="0" step="${step||'1'}"`:''}></label>`,area=(label,key,value='')=>`<label class="contract-edit-field contract-edit-wide"><span>${label}</span><textarea class="textarea" name="${key}">${esc(value||c[key]||'')}</textarea></label>`;
 const deliverableText=(c.deliverables||[]).map(x=>`${x.name} | ${x.target} | ${x.actual}`).join('\n'),checklistText=(c.compliance||[]).map(x=>`${x.name} | ${x.status} | ${x.detail}`).join('\n');
 return `<form class="card contract-edit-form" data-contract-user="${esc(u.id)}"><div class="card-head"><div><div class="card-title">Edit terms · ${esc(u.name)}</div><div class="card-sub">Update the agreement details, compensation, and work commitments.</div></div><button class="btn" type="button" data-contract-cancel>Cancel</button></div><div class="contract-edit-section"><h2>Contract summary & dates</h2><div class="contract-edit-grid">${input('Agreement type','agreementType')}${input('Status','status')}${input('Role','role')}${input('EXL contact','exlContact')}${input('Agreement date','agreementDate','date')}${input('SOW start','sowStart','date')}${input('SOW end','sowEnd','date')}${input('Extension deadline','extensionDeadline','date')}${input('Commission window end','commissionWindowEnd','date')}${input('Location','location')}${input('Governing law','governingLaw')}${input('Payment terms','paymentTerms')}</div></div><div class="contract-edit-section"><h2>Compensation & commission rules</h2><div class="contract-edit-grid">${input('Hourly rate ($)','hourlyRate','number','0.01')}${input('First month cap (hours)','firstMonthCap','number')}${input('Monthly cap after first month (hours)','monthlyCap','number')}${input('Extra hours approval','extraHours')}${input('Travel & expenses','travelExpenses')}${input('One-time incentive ($)','oneTimeIncentive','number')}${input('Large MSA threshold ($M)','largeMsaThreshold','number')}${input('Large MSA commission ($)','largeMsaCommission','number')}${input('Other MSA commission ($)','otherMsaCommission','number')}${input('SOW commission · months 1–12 (%)','sowYearOnePercent','number','0.1')}${input('SOW commission · months 13–24 (%)','sowYearTwoPercent','number','0.1')}${input('Hours used this month','hoursUsed','number','0.1')}${input('Monthly tracked hours cap','hoursCap','number','0.1')}</div></div><div class="contract-edit-section"><h2>Deliverables & compliance</h2><div class="contract-edit-grid">${area('Deliverables · one per line: name | target | actual','deliverablesText',deliverableText)}${area('Compliance checklist · one per line: item | status | note','complianceText',checklistText)}</div></div><div class="contract-edit-section"><h2>Scope & obligations</h2><div class="contract-edit-grid">${area('Scope of work','scope')}${area('Terms and conditions','conditions')}${area('Restrictions & post-exit obligations','restrictions')}</div></div><div class="contract-save-row"><span>Saving makes these terms visible to this person.</span><button class="btn primary" type="submit">Save contract terms</button></div></form>`
}
function contractPage(){

 if(isAdmin()){
  const people=db.users.filter(u=>u.role==='User');if(!people.some(u=>u.id===selectedContractUser))selectedContractUser=people[0]?.id;
  const person=people.find(u=>u.id===selectedContractUser);if(!person)return `${head('ADMINISTRATION','Advisor and POC contract terms','No advisor or internal POC accounts are configured.')}`;
  return `${head('ADMINISTRATION','Advisor and POC contract terms','Review agreement dates, compensation, deliverables, and obligations for each person.')}<div class="contract-toolbar"><label><span>Choose advisor / POC</span><select class="select" id="contract-user-select">${people.map(u=>`<option value="${esc(u.id)}" ${u.id===person.id?'selected':''}>${esc(u.name)} · ${esc(u.title)}</option>`).join('')}</select></label>${editContractsMode?'<span class="pill orange">Editing terms</span>':'<button class="btn primary" type="button" data-contract-edit>Edit selected terms</button>'}</div>${editContractsMode?contractEditorForm(person):contractDashboard(person,contractFor(person.id))}`
 }
 return `${head('MY WORKSPACE','My contract terms','Review the agreement details and conditions recorded for your profile.')}${contractDashboard(user(),contractFor(user().id))}`
}
function adminPage(){if(!isAdmin()){page='home';return homePage()}return `${head('WORKSPACE ADMIN','Workspace users','Every advisor and EXL POC can work with any club. Interaction and next-step editing follows record ownership.','')}<div class="admin-grid"><section class="card"><div class="card-head"><div><div class="card-title">Shared club directory</div><div class="card-sub">All clubs are available to all advisors and EXL POCs.</div></div></div><div class="card-body"><div class="note">Anyone on the team can log a meeting with any NFL, MLB, MLS, NHL, or NBA club and see its shared interaction history.</div></div></section><section class="card"><div class="card-head"><div><div class="card-title">Workspace users</div><div class="card-sub">Demo accounts and their workspace roles</div></div></div><div class="card-body">${db.users.map(u=>`<div class="admin-user"><div><div class="cell-title">${esc(u.name)}</div><div class="cell-sub">${esc(u.title)}</div></div><span class="pill ${u.role==='Admin'?'blue':'green'}">${u.role}</span></div>`).join('')}<div class="note" style="margin-top:14px">Regular users can create interactions and meetings for any club, and manage their own records. Admins can review and manage all activity.</div></div></section></div>`}
function openClub(id){selectedClub=id;clubTab='history';page='club';app()}
