 const cs=$('#club-search'),lf=$('#league-filter');if(cs||lf){const filter=()=>{const term=(cs?.value||'').toLowerCase(),league=lf?.value||'all',results=$('#club-results');results.innerHTML=clubCards(visibleClubs().filter(c=>c.name.toLowerCase().includes(term)&&(league==='all'||c.league===league)));results.querySelectorAll('[data-open-club]').forEach(b=>b.onclick=()=>openClub(b.dataset.openClub))};cs?.addEventListener('input',filter);lf?.addEventListener('change',filter)}
