function collectRows(form,kind){return [...form.querySelectorAll(`.${kind==='follow'?'follow-row':'attendee-row'}`)]}
function saveInteraction(e){
 e.preventDefault();if(isAdmin()&&!editingInteraction){toast('The Admin account reviews existing activity. Sign in as an EXL user to log an interaction.');return}
 const form=e.target,fd=new FormData(form),clubId=fd.get('clubId');if(!canSeeClub(clubId)){toast('You do not have access to that club');return}
 const attendees=kind=>collectRows(form,kind).map(r=>({name:r.querySelector('[name='+kind+'Name]')?.value.trim()||'',role:r.querySelector('[name='+kind+'Role]')?.value.trim()||''})).filter(a=>a.name);
 const stakeholders=attendees('stakeholder'),participants=attendees('participant');
 if(fd.get('recordMode')==='planned'){
  const date=fd.get('date');if(date<dt()){toast('Choose today or a future date for a planned meeting');return}
  const meeting={id:'m-'+Date.now(),clubId,date,time:fd.get('meetingTime')||'',meetingType:fd.get('meetingType')||'First meeting',exlPoc:participants[0]?.name||'',clubPoc:stakeholders[0]?.name||'',clubPocDesignation:stakeholders[0]?.role||'',participants:[stakeholders[0]?.name,participants[0]?.name].filter(Boolean),agenda:fd.get('summary').trim(),owner:user().id,status:'Planned'};
  db.meetings.push(meeting);save();editingInteraction=null;meetingToComplete=null;page='club';selectedClub=clubId;clubTab='meetings';app();toast('Planned meeting saved. It is not counted as a completed interaction.');return;
 }
 const followups=collectRows(form,'follow').map(r=>({id:r.dataset.id||'f-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),description:r.querySelector('[name=followDescription]').value.trim(),owner:r.querySelector('[name=followOwner]').value,due:r.querySelector('[name=followDue]').value,status:r.querySelector('[name=followStatus]').value})).filter(f=>f.description);if(followups.some(f=>!f.due)){toast('Add a due date for each next step');return}
 const prev=editingInteraction,nextDate=fd.get('nextMeeting');const record={id:prev?.id||'i-'+Date.now(),clubId,date:fd.get('date'),stakeholders,participants,exlPoc:participants[0]?.name||'',clubPoc:stakeholders[0]?.name||'',clubPocDesignation:stakeholders[0]?.role||'',nextStepType:fd.get('nextStepType')||'Yet to be decided',summary:fd.get('summary').trim(),capabilities:fd.getAll('capability'),other:fd.get('other')?.trim()||'',owner:prev?.owner||user().id,sample:false,followups,nextMeeting:nextDate||'',nextMeetingTime:fd.get('nextMeetingTime')||'',nextAgenda:fd.get('nextAgenda')?.trim()||''};if(prev)db.interactions=db.interactions.map(x=>x.id===prev.id?record:x);else db.interactions.push(record);
 let linked=prev?.meetingId&&db.meetings.find(m=>m.id===prev.meetingId);if(meetingToComplete){linked=db.meetings.find(m=>m.id===meetingToComplete);if(linked){linked.status='Completed';linked.interactionId=record.id;record.meetingId=linked.id}meetingToComplete=null}else if(nextDate){if(linked){linked.date=nextDate;linked.time=record.nextMeetingTime;linked.agenda=record.nextAgenda;linked.interactionId=record.id}else{linked={id:'m-'+Date.now(),clubId,date:nextDate,time:record.nextMeetingTime,interactionId:record.id,meetingType:'Follow-up meeting',exlPoc:record.exlPoc,clubPoc:record.clubPoc,clubPocDesignation:record.clubPocDesignation,participants:stakeholders.map(a=>a.name).concat(participants.map(a=>a.name)),agenda:record.nextAgenda,owner:user().id,status:'Planned'};db.meetings.push(linked)}record.meetingId=linked.id}else if(linked&&linked.status==='Planned'){linked.status='Canceled'}
 save();editingInteraction=null;page='club';selectedClub=clubId;clubTab='history';app();toast(prev?'Interaction updated':'Interaction saved')
}
function changeFollowup(id,status){let found;db.interactions.forEach(i=>i.followups.forEach(f=>{if(f.id===id)found={i,f}}));if(!found||(!isAdmin()&&found.f.owner!==user().id&&found.i.owner!==user().id)){toast('You do not have access to update this action');return}found.f.status=status;save();renderPage();toast(`Next step marked ${status.toLowerCase()}`)}
function meetingModal(id=''){
 const m=db.meetings.find(x=>x.id===id);if(m&&!isAdmin()&&m.owner!==user().id)return;
 const content=`<div class="modal-backdrop" id="modal-backdrop"><div class="modal"><div class="modal-head"><div class="modal-title">${m?'Edit planned meeting':'Plan a meeting'}</div><button class="close" data-close>×</button></div><form class="modal-body" id="meeting-form"><div class="form-grid"><div class="field"><label>Club *</label><select class="select" name="clubId" required>${visibleClubs().map(c=>`<option value="${c.id}" ${c.id===(m?.clubId||selectedClub)?'selected':''}>${esc(c.name)} · ${c.league}</option>`).join('')}</select></div><div class="field"><label>Meeting date *</label><input class="input" type="date" name="date" value="${m?.date||''}" required></div><div class="field"><label>Meeting time</label><input class="input" type="time" name="time" value="${m?.time||''}"></div><div class="field"><label>Meeting type *</label><select class="select" name="meetingType"><option ${m?.meetingType==='First meeting'?'selected':''}>First meeting</option><option ${m?.meetingType==='Follow-up meeting'?'selected':''}>Follow-up meeting</option></select></div><div class="field"><label>EXL POC *</label><input class="input" name="exlPoc" value="${esc(m?.exlPoc||user().name)}" required></div><div class="field"><label>Club/client POC *</label><input class="input" name="clubPoc" value="${esc(m?.clubPoc||'')}" required></div><div class="field"><label>Designation *</label><input class="input" name="clubPocDesignation" value="${esc(m?.clubPocDesignation||'')}" required></div><div class="field full"><label>Meeting description / agenda</label><textarea class="textarea" name="agenda" placeholder="What do you plan to discuss?">${esc(m?.agenda||'')}</textarea></div></div><div class="form-actions"><button type="button" class="btn" data-close>Cancel</button><button class="btn primary">Save meeting</button></div></form></div></div>`;
 document.body.insertAdjacentHTML('beforeend',content);$('#modal-backdrop').onclick=e=>{if(e.target.id==='modal-backdrop'||e.target.closest('[data-close]'))$('#modal-backdrop').remove()};
 $('#meeting-form').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target),clubId=d.get('clubId');if(!canSeeClub(clubId)){toast('You do not have access to that club');return}const record={id:m?.id||`m-${Date.now()}`,clubId,date:d.get('date'),time:d.get('time')||'',interactionId:m?.interactionId||'',meetingType:d.get('meetingType'),exlPoc:d.get('exlPoc').trim(),clubPoc:d.get('clubPoc').trim(),clubPocDesignation:d.get('clubPocDesignation').trim(),participants:[d.get('clubPoc').trim(),d.get('exlPoc').trim()],agenda:d.get('agenda').trim(),owner:m?.owner||user().id,status:'Planned'};if(m)db.meetings=db.meetings.map(x=>x.id===m.id?record:x);else db.meetings.push(record);save();$('#modal-backdrop').remove();renderPage();toast(m?'Meeting updated':'Meeting planned')}
}
function cancelMeeting(id){const m=db.meetings.find(x=>x.id===id);if(!m||(!isAdmin()&&m.owner!==user().id))return;if(confirm('Cancel this planned meeting?')){m.status='Canceled';save();renderPage();toast('Meeting canceled')}}
function completeMeeting(id){const m=db.meetings.find(x=>x.id===id);if(!m||isAdmin()||m.owner!==user().id)return;meetingToComplete=id;editingInteraction=null;page='log';app();const s=document.querySelector('[name=clubId]'),d=document.querySelector('[name=date]');if(s){s.value=m.clubId;s.dispatchEvent(new Event('change'))}if(d)d.value=m.date;toast('Add the POC details and discussion notes to complete this meeting')}
// Keep next step identifiers stable when an interaction is edited.
function followRow(f){return `<div class="follow-row" data-id="${esc(f.id||'')}"><input class="mini-input" name="followDescription" placeholder="Action description" value="${esc(f.description)}"><select class="mini-input" name="followOwner">${db.users.map(u=>`<option value="${u.id}" ${u.id===f.owner?'selected':''}>${esc(u.name)}</option>`).join('')}</select><input class="mini-input" type="date" name="followDue" value="${f.due||''}"><select class="mini-input" name="followStatus">${['Open','Done','Canceled'].map(s=>`<option ${f.status===s?'selected':''}>${s}</option>`).join('')}</select><button type="button" class="action-link" data-remove-row>×</button></div>`}
// Defer completing a planned meeting until its interaction notes are saved.
function completeMeeting(id){const m=db.meetings.find(x=>x.id===id);if(!m||isAdmin()||m.owner!==user().id)return;meetingToComplete=id;editingInteraction=null;page='log';app();const s=document.querySelector('[name=clubId]'),d=document.querySelector('[name=date]');if(s){s.value=m.clubId;s.dispatchEvent(new Event('change'))}if(d)d.value=m.date;toast('Add the POC details and discussion notes to complete this meeting')}
